setInterval(()=>{if(datasetBusy&&!$('#modal').open)refreshDatasetPanel();},3000);

// Refresh only the search panel while a job runs; preserve unsaved notes/corrections.
let websitePollBusy=false;
setInterval(async()=>{
 if(route!=='company'||!$('#website-search-panel .discovery-progress')||websitePollBusy||$('#modal').open)return;
 const id=filters.id;websitePollBusy=true;
 try{
  const [c,status]=await Promise.all([api('/companies/'+id),api(`/companies/${id}/website-search`)]);
  if(route!=='company'||filters.id!==id)return;
  const panel=$('#website-search-panel');if(!panel||panel.contains(document.activeElement))return;
  panel.innerHTML=websiteResult(c,status);
  if(status.job&&!['queued','running'].includes(status.job.state)){
   const hasDraft=!!$('#activity-form [name=text]')?.value.trim()||$('#company-edit')?.open||document.activeElement?.closest('form');
   if(status.job.result?.applied&&!hasDraft)await render();
   else if(status.job.result?.applied){const refresh=document.createElement('button');refresh.textContent='Actualiser les coordonnées du dossier';refresh.dataset.action='reload';panel.appendChild(refresh);}
  }
 }catch(e){toast(e.message);}finally{websitePollBusy=false;}
},3000);

